<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';import { useRoute } from 'vue-router';import { ArrowLeft, Printer } from '@lucide/vue';import { api } from '../api';import Modal from '../components/Modal.vue'
const window=globalThis.window
const route=useRoute();const invoice=ref<any>(null);const error=ref('');const showPayment=ref(false);const saving=ref(false);const payment=reactive({amount_egp:'',paid_on:new Date().toISOString().slice(0,10),method:'bank_transfer',reference:'',notes:''});const money=(minor:number)=>new Intl.NumberFormat('en-EG',{style:'currency',currency:'EGP'}).format((minor||0)/100);const printInvoice=()=>window.print()
async function load(){try{invoice.value=(await api.get(`/invoices/${route.params.id}`)).data;payment.amount_egp=((invoice.value.total_minor_units-invoice.value.amount_paid_minor_units)/100).toFixed(2)}catch(e:any){error.value=e.response?.data?.message||'Invoice could not be loaded.'}}
async function issue(){saving.value=true;try{await api.post(`/invoices/${invoice.value.id}/issue`);await load()}catch(e:any){error.value=e.response?.data?.message||'Invoice could not be issued.'}finally{saving.value=false}}
async function recordPayment(){saving.value=true;try{await api.post(`/invoices/${invoice.value.id}/payments`,payment);showPayment.value=false;await load()}catch(e:any){error.value=Object.values(e.response?.data?.errors||{error:[e.response?.data?.message||'Payment could not be saved.']}).flat().join(' ')}finally{saving.value=false}}
onMounted(load)
</script>
<template><div class="invoice-detail-page"><div class="invoice-actions"><RouterLink to="/finance" class="button secondary"><ArrowLeft/>Finance</RouterLink><div><button v-if="invoice?.status==='draft'" class="button primary" :disabled="saving" @click="issue">Issue invoice</button><button v-if="invoice && !['draft','paid','void'].includes(invoice.status)" class="button primary" @click="showPayment=true">Record payment</button><button class="button secondary" @click="window.print()"><Printer/>Print</button></div></div><div v-if="error" class="detail-alert">{{error}}</div><article v-if="invoice" class="invoice-sheet"><header><div><span class="eyebrow">INVOICE</span><h1>{{invoice.invoice_number}}</h1></div><div><strong>{{invoice.status.replace('_',' ')}}</strong><small>Issued {{invoice.issue_date}} · Due {{invoice.due_date||'on receipt'}}</small></div></header><section class="invoice-parties"><div><small>FROM</small><strong>Exousia Realty workspace</strong></div><div><small>BILL TO</small><strong>{{invoice.billing_name}}</strong><span>{{invoice.billing_phone}}</span></div></section><table><thead><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Total</th></tr></thead><tbody><tr v-for="item in invoice.items" :key="item.id"><td>{{item.description}}</td><td>{{item.quantity}}</td><td>{{money(item.unit_price_minor_units)}}</td><td>{{money(item.line_total_minor_units)}}</td></tr></tbody></table><section class="invoice-totals"><div><span>Subtotal</span><strong>{{money(invoice.subtotal_minor_units)}}</strong></div><div><span>Tax</span><strong>{{money(invoice.tax_minor_units)}}</strong></div><div><span>Total</span><strong>{{money(invoice.total_minor_units)}}</strong></div><div><span>Balance due</span><strong>{{money(invoice.total_minor_units-invoice.amount_paid_minor_units)}}</strong></div></section><p v-if="invoice.notes" class="invoice-notes">{{invoice.notes}}</p><section v-if="invoice.payments?.length" class="invoice-payments"><h2>Payment history</h2><div v-for="item in invoice.payments" :key="item.id"><span>{{item.paid_on}} · {{item.method.replace('_',' ')}} · {{item.reference||'No reference'}}</span><strong>{{money(item.amount_minor_units)}}</strong></div></section></article><Modal v-if="showPayment" title="Record invoice payment" @close="showPayment=false"><form class="form-grid" @submit.prevent="recordPayment"><label>Amount (EGP)<input v-model="payment.amount_egp" required></label><label>Paid on<input v-model="payment.paid_on" type="date" required></label><label>Method<select v-model="payment.method"><option value="bank_transfer">Bank transfer</option><option value="cash">Cash</option><option value="cheque">Cheque</option><option value="card">Card</option><option value="other">Other</option></select></label><label>Reference<input v-model="payment.reference"></label><label class="full">Notes<textarea v-model="payment.notes"></textarea></label><div class="form-actions full"><button type="button" class="button secondary" @click="showPayment=false">Cancel</button><button class="button primary" :disabled="saving">Save payment</button></div></form></Modal></div></template>
